function Cesta({ cart, onClose, onChange }) {
  const lines = PRODUCTS.filter((p) => cart[p.id] > 0);
  const subtotal = lines.reduce((s, p) => s + p.price * cart[p.id], 0);
  const freeFrom = 80;

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <>
      <div className="veil" onClick={onClose} />
      <aside className="drawer" role="dialog" aria-modal="true" aria-labelledby="cesta-title">
        <div className="drawer-head">
          <h2 id="cesta-title">Tu cesta</h2>
          <button className="close" onClick={onClose} autoFocus>Cerrar</button>
        </div>
        <div className="drawer-body">
          {lines.length === 0 ? (
            <div className="empty">
              <p>Todavía no has elegido ninguna pieza.</p>
              <a href="#coleccion" className="btn btn-line" onClick={onClose}>Ver la colección</a>
            </div>
          ) : (
            lines.map((p) => (
              <div className="line" key={p.id}>
                <div className="line-thumb"><Fabric kind={p.fabric} tone={p.tone} uid={`t-${p.id}`} withDaisy={false} /></div>
                <div>
                  <div className="line-name">{p.name}</div>
                  <div className="qty">
                    <button onClick={() => onChange(p.id, -1)} aria-label={`Quitar una unidad de ${p.name}`}>−</button>
                    <span aria-live="polite">{cart[p.id]}</span>
                    <button onClick={() => onChange(p.id, 1)} aria-label={`Añadir una unidad de ${p.name}`}>+</button>
                  </div>
                </div>
                <div className="line-meta">{euro(p.price * cart[p.id])}</div>
              </div>
            ))
          )}
        </div>
        {lines.length > 0 && (
          <div className="drawer-foot">
            <div className="total"><span>Subtotal</span><span>{euro(subtotal)}</span></div>
            <p className="ship">
              {subtotal >= freeFrom
                ? "El envío es gratuito en este pedido."
                : `Te faltan ${euro(freeFrom - subtotal)} para el envío gratuito.`}
            </p>
            <button className="btn btn-solid">Ir al pago</button>
          </div>
        )}
      </aside>
    </>
  );
}

