// Marca con .in los bloques .rv cuando entran en pantalla (una sola vez)
function useReveal() {
  useEffect(() => {
    const els = document.querySelectorAll(".la .rv");
    if (!("IntersectionObserver" in window)) {
      els.forEach((el) => el.classList.add("in"));
      return;
    }
    const io = new IntersectionObserver(
      (entries) =>
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add("in");
            io.unobserve(e.target);
          }
        }),
      { rootMargin: "0px 0px -8% 0px" }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, []);
}

export default function App() {
  const [cart, setCart] = useState({});
  const [bagOpen, setBagOpen] = useState(false);
  const [toast, setToast] = useState(null);

  useReveal();

  const count = Object.values(cart).reduce((a, b) => a + b, 0);

  const showToast = (text) => {
    setToast(text);
    clearTimeout(window.__lolitaToast);
    window.__lolitaToast = setTimeout(() => setToast(null), 2600);
  };

  const change = (id, delta) =>
    setCart((c) => {
      const next = { ...c, [id]: Math.max(0, (c[id] || 0) + delta) };
      if (next[id] === 0) delete next[id];
      return next;
    });

  const add = (id) => {
    change(id, 1);
    const p = PRODUCTS.find((x) => x.id === id);
    showToast(`Añadido a la cesta: ${p.name}`);
  };

  return (
    <div className="la">
      <style>{CSS}</style>
      <a className="skip" href="#contenido">Saltar al contenido</a>
      <Header count={count} onOpenBag={() => setBagOpen(true)} />
      <main id="contenido">
        <Hero />
        <Cinta />
        <Historia />
        <Coleccion cart={cart} onAdd={add} />
        <Proceso />
        <Personaliza onToast={showToast} />
        <Cartas />
      </main>
      <Footer />
      {bagOpen && <Cesta cart={cart} onClose={() => setBagOpen(false)} onChange={change} />}
      {toast && <div className="toast" role="status">{toast}</div>}
    </div>
  );
}
